const { execSync } = require('child_process');
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
const db = `${prj}/IMPAR_OS/database/impar.db`;
const ts = new Date().toISOString();
const get = (q) => { try { return execSync(`sqlite3 "${db}" "${q}"`, {timeout:5000}).toString().trim(); } catch(e) { return '0'; } };
const today = new Date().toISOString().substring(0,10);
const exec_total = get(`SELECT COUNT(*) FROM executions WHERE timestamp LIKE '${today}%';`);
const exec_ok = get(`SELECT COUNT(*) FROM executions WHERE timestamp LIKE '${today}%' AND status='ok';`);
const errors = get(`SELECT COUNT(*) FROM errors WHERE timestamp LIKE '${today}%';`);
const ai_calls = get(`SELECT COUNT(*) FROM executions WHERE timestamp LIKE '${today}%' AND ai_used=1;`);
const tokens_saved = get(`SELECT COALESCE(SUM(tokens_saved),0) FROM token_savings WHERE date='${today}';`);
const report = { date: today, executions: { total: parseInt(exec_total), ok: parseInt(exec_ok) }, errors: parseInt(errors), ai_calls_today: parseInt(ai_calls), tokens_saved_today: parseInt(tokens_saved), ai_used: false, generated_at: ts };
const rpath = `${prj}/IMPAR_OS/reports/daily-${today}.json`;
try { require('fs').writeFileSync(rpath, JSON.stringify(report, null, 2)); } catch(e) {}
return [{ json: report }];
